def transform2(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0]); bg=grid[0][0]
    for color in {v for row in grid for v in row if v!=bg}:
        pts={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color}
        for dr,dc in ((1,1),(1,-1)):
            # Each adjacent diagonal pair initiates extensions outward at either endpoint.
            for r,c in pts:
                if (r+dr,c+dc) in pts:
                    for sr,sc,vr,vc in ((r-dr,c-dc,-dr,-dc),(r+2*dr,c+2*dc,dr,dc)):
                        rr,cc=sr,sc
                        while 0<=rr<h and 0<=cc<w and grid[rr][cc]==bg:
                            out[rr][cc]=color
                            rr+=vr;cc+=vc
    return out
