def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = grid[0][0]

    # Continue any diagonal pair of a non-background color outward along
    # its diagonal, stopping at the grid edge or another non-background cell.
    colors = {value for row in grid for value in row if value != background}
    for color in colors:
        points = {
            (r, c)
            for r, row in enumerate(grid)
            for c, value in enumerate(row)
            if value == color
        }
        for dr, dc in ((1, 1), (1, -1)):
            for r, c in points:
                if (r + dr, c + dc) not in points:
                    continue
                for rr, cc, step_r, step_c in (
                    (r - dr, c - dc, -dr, -dc),
                    (r + 2 * dr, c + 2 * dc, dr, dc),
                ):
                    while (
                        0 <= rr < h
                        and 0 <= cc < w
                        and grid[rr][cc] == background
                    ):
                        out[rr][cc] = color
                        rr += step_r
                        cc += step_c
    return out
